import { nanoid } from "nanoid";
import bcrypt from "bcryptjs";
import { User } from "@prisma/client";
import { getPrisma } from "@poker-champ/db";
import { logger } from "../../lib/logger.js";

type AuthToken = string;
const DEFAULT_SESSION_TTL_DAYS = 14;
const MIN_USERNAME_LEN = 3;
const MAX_USERNAME_LEN = 24;
const STARTING_BANKROLL_CENTS = 1_000_000;

export class AuthService {
  static async register(
    email: string,
    password: string,
    displayName: string,
    usernameInput?: string,
  ): Promise<{ token: AuthToken; user: User }> {
    const prisma = getPrisma();

    const normalizedEmail = this.normalizeEmail(email);
    const existing = await prisma.user.findUnique({ where: { email: normalizedEmail } });
    if (existing) {
      throw new Error("Email already registered");
    }

    const handle = await this.allocateUsername(normalizedEmail, usernameInput);
    const passwordHash = await bcrypt.hash(password, 12);

    const user = await prisma.user.create({
      data: {
        email: normalizedEmail,
        username: handle.username,
        usernameNormalized: handle.usernameNormalized,
        passwordHash,
        displayName,
        role: "USER",
        bankrollCents: STARTING_BANKROLL_CENTS,
      },
    });

    const token = await this.createSession(user.id);
    return { token, user };
  }

  static async login(email: string, password: string): Promise<{ token: AuthToken; user: User }> {
    const prisma = getPrisma();
    const normalizedEmail = this.normalizeEmail(email);

    const user = await prisma.user.findUnique({ where: { email: normalizedEmail } });
    if (!user) {
      throw new Error("Invalid credentials");
    }

    if (user.isBanned || user.deletedAt) {
      throw new Error("Account is suspended");
    }

    const isValid = await bcrypt.compare(password, user.passwordHash);
    if (!isValid) {
      throw new Error("Invalid credentials");
    }

    const hydrated = await this.ensureUserHandle(user);
    await this.revokeUserSessions(hydrated.id);
    const token = await this.createSession(user.id);
    return { token, user: hydrated };
  }

  static async validateSession(token: string): Promise<User | null> {
    const prisma = getPrisma();
    try {
      const session = await prisma.userSession.findUnique({
        where: { id: token },
        include: { user: true },
      });

      if (!session) return null;

      if (session.expiresAt < new Date()) {
        await prisma.userSession.delete({ where: { id: token } });
        return null;
      }

      if (session.user.isBanned || session.user.deletedAt) return null;

      const now = new Date();
      await prisma.userSession.update({
        where: { id: token },
        data: {
          lastUsedAt: now,
          expiresAt: new Date(now.getTime() + this.getSessionTtlMs()),
        },
      });

      return this.ensureUserHandle(session.user);
    } catch (err: any) {
      logger.error({ err }, "validateSession failed due to backend error");
      const backendErr = new Error("Auth backend unavailable");
      (backendErr as any).code = "AUTH_BACKEND_UNAVAILABLE";
      throw backendErr;
    }
  }

  static async revokeSession(token: string): Promise<void> {
    const prisma = getPrisma();
    await prisma.userSession.deleteMany({ where: { id: token } });
  }

  static async revokeUserSessions(userId: string): Promise<void> {
    const prisma = getPrisma();
    await prisma.userSession.deleteMany({ where: { userId } });
  }

  private static async createSession(userId: string): Promise<string> {
    const prisma = getPrisma();
    const token = nanoid(32);
    const now = new Date();
    const expiresAt = new Date(now.getTime() + this.getSessionTtlMs());

    await prisma.userSession.create({
      data: {
        id: token,
        userId,
        createdAt: now,
        lastUsedAt: now,
        expiresAt,
      },
    });

    return token;
  }

  private static normalizeEmail(email: string) {
    return email.trim().toLowerCase();
  }

  private static normalizeUsername(raw: string): string {
    const cleaned = raw
      .trim()
      .replace(/\s+/g, "_")
      .replace(/[^A-Za-z0-9_]/g, "")
      .toLowerCase();
    return cleaned.slice(0, MAX_USERNAME_LEN);
  }

  private static fallbackUsernameFromEmail(email: string): string {
    const prefix = email.split("@")[0] ?? "player";
    const normalized = this.normalizeUsername(prefix);
    if (normalized.length >= MIN_USERNAME_LEN) return normalized;
    return "player";
  }

  private static async allocateUsername(email: string, usernameInput?: string) {
    const prisma = getPrisma();
    const requested = typeof usernameInput === "string" ? this.normalizeUsername(usernameInput) : "";
    const base = requested || this.fallbackUsernameFromEmail(email);

    if (requested) {
      if (requested.length < MIN_USERNAME_LEN) {
        throw new Error(`Username must be at least ${MIN_USERNAME_LEN} characters`);
      }
      const existing = await prisma.user.findFirst({ where: { usernameNormalized: requested } });
      if (existing) {
        throw new Error("Username already taken");
      }
      return { username: requested, usernameNormalized: requested };
    }

    for (let attempt = 0; attempt < 50; attempt++) {
      const suffix = attempt === 0 ? "" : `_${nanoid(4).toLowerCase()}`;
      const candidate = `${base}${suffix}`.slice(0, MAX_USERNAME_LEN);
      const normalized = this.normalizeUsername(candidate);
      if (normalized.length < MIN_USERNAME_LEN) continue;

      const existing = await prisma.user.findFirst({ where: { usernameNormalized: normalized } });
      if (!existing) {
        return { username: normalized, usernameNormalized: normalized };
      }
    }

    throw new Error("Could not allocate username");
  }

  private static async ensureUserHandle(user: User): Promise<User> {
    if (user.username && user.usernameNormalized) return user;

    const prisma = getPrisma();
    const handle = await this.allocateUsername(user.email, user.username ?? undefined);
    return prisma.user.update({
      where: { id: user.id },
      data: {
        username: handle.username,
        usernameNormalized: handle.usernameNormalized,
      },
    });
  }

  private static getSessionTtlMs() {
    const parsed = Number.parseInt(process.env.SESSION_TTL_DAYS ?? "", 10);
    const days = Number.isFinite(parsed) && parsed > 0 ? parsed : DEFAULT_SESSION_TTL_DAYS;
    return days * 24 * 60 * 60 * 1000;
  }
}

import type { NextFunction, Request, Response } from "express";
import { AuthService } from "./AuthService.js";

function parseBearerToken(req: Request): string | null {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return null;
  }
  const token = authHeader.slice("Bearer ".length).trim();
  return token.length > 0 ? token : null;
}

export async function requireAuth(req: Request, res: Response, next: NextFunction) {
  try {
    const token = parseBearerToken(req);
    if (!token) {
      res.status(401).json({ error: "Missing or invalid Authorization header" });
      return;
    }

    const user = await AuthService.validateSession(token);
    if (!user) {
      res.status(401).json({ error: "Invalid or expired session" });
      return;
    }

    req.user = user;
    next();
  } catch (err: any) {
    if (err?.code === "AUTH_BACKEND_UNAVAILABLE") {
      res.status(503).json({ error: "Auth service unavailable", code: "AUTH_BACKEND_UNAVAILABLE" });
      return;
    }
    res.status(500).json({ error: "Internal Server Error" });
  }
}

import { getPrisma } from "@poker-champ/db";

type SeatSessionState = "SEATED_ACTIVE" | "SEATED_SITTING_OUT" | "LEFT";

type UpsertSeatInput = {
  tableId: string;
  userId: string;
  seat: number;
  stackCentsSnapshot: number;
  buyInCents: number;
  handIdSnapshot?: string;
  schemaVersion?: number;
};

type ReapParams = {
  tableId: string;
  retentionHours: number;
  hardDeleteHours: number;
};

type SoftExpiredSeatSession = {
  id: string;
  tableId: string;
  userId: string;
  seat: number;
  stackCentsSnapshot: number;
  state: SeatSessionState;
  disconnectAt: Date | null;
};

type RestorableSeatSession = {
  id: string;
  tableId: string;
  userId: string;
  seat: number;
  stackCentsSnapshot: number;
  buyInCents: number;
  state: SeatSessionState;
  handIdSnapshot: string | null;
  schemaVersion: number;
  disconnectAt: Date | null;
  lastSeenAt: Date;
};

type SittingOutSessionTimestamp = {
  userId: string;
  disconnectAt: Date | null;
};

export class TableSeatSessionService {
  static async listRestorableSessionsForTable(params: {
    tableId: string;
    retentionHours: number;
  }): Promise<RestorableSeatSession[]> {
    const prisma = getPrisma() as any;
    const retentionHours = Math.max(1, Math.floor(params.retentionHours));
    const softCutoff = new Date(Date.now() - retentionHours * 60 * 60 * 1000);
    const rows: RestorableSeatSession[] = await prisma.tableSeatSession.findMany({
      where: {
        tableId: params.tableId,
        state: { in: ["SEATED_ACTIVE", "SEATED_SITTING_OUT"] },
        OR: [{ disconnectAt: null }, { disconnectAt: { gte: softCutoff } }],
      },
      orderBy: [{ seat: "asc" }, { updatedAt: "desc" }],
      select: {
        id: true,
        tableId: true,
        userId: true,
        seat: true,
        stackCentsSnapshot: true,
        buyInCents: true,
        state: true,
        handIdSnapshot: true,
        schemaVersion: true,
        disconnectAt: true,
        lastSeenAt: true,
      },
    });
    return rows;
  }

  static async markLeftBySessionId(params: {
    id: string;
  }): Promise<void> {
    const prisma = getPrisma() as any;
    await prisma.tableSeatSession.updateMany({
      where: { id: params.id },
      data: {
        state: "LEFT" as SeatSessionState,
        lastSeenAt: new Date(),
      },
    });
  }

  static async reapExpiredSessionsForTable(params: ReapParams): Promise<{
    softExpired: SoftExpiredSeatSession[];
    hardDeletedCount: number;
  }> {
    const prisma = getPrisma() as any;
    const now = Date.now();
    const retentionHours = Math.max(1, Math.floor(params.retentionHours));
    const hardDeleteHours = Math.max(retentionHours, Math.floor(params.hardDeleteHours));
    const softCutoff = new Date(now - retentionHours * 60 * 60 * 1000);
    const hardCutoff = new Date(now - hardDeleteHours * 60 * 60 * 1000);

    return prisma.$transaction(async (tx: any) => {
      const softExpired: SoftExpiredSeatSession[] = await tx.tableSeatSession.findMany({
        where: {
          tableId: params.tableId,
          state: "SEATED_SITTING_OUT",
          disconnectAt: { not: null, lte: softCutoff, gt: hardCutoff },
        },
        select: {
          id: true,
          tableId: true,
          userId: true,
          seat: true,
          stackCentsSnapshot: true,
          state: true,
          disconnectAt: true,
        },
      });

      if (softExpired.length > 0) {
        await tx.tableSeatSession.updateMany({
          where: { id: { in: softExpired.map((row) => row.id) } },
          data: {
            state: "LEFT",
            lastSeenAt: new Date(),
          },
        });
      }

      const hardDeleted = await tx.tableSeatSession.deleteMany({
        where: {
          tableId: params.tableId,
          state: { in: ["LEFT", "SEATED_SITTING_OUT"] },
          disconnectAt: { not: null, lte: hardCutoff },
        },
      });

      return {
        softExpired,
        hardDeletedCount: hardDeleted.count ?? 0,
      };
    });
  }

  static async findRejoinableSession(params: {
    tableId: string;
    userId: string;
  }): Promise<{
    tableId: string;
    userId: string;
    seat: number;
    stackCentsSnapshot: number;
    buyInCents: number;
    state: SeatSessionState;
  } | null> {
    const prisma = getPrisma() as any;
    const row = await prisma.tableSeatSession.findUnique({
      where: { tableId_userId: { tableId: params.tableId, userId: params.userId } },
      select: {
        tableId: true,
        userId: true,
        seat: true,
        stackCentsSnapshot: true,
        buyInCents: true,
        state: true,
      },
    });
    if (!row) return null;
    if (row.state === "LEFT") return null;
    return row;
  }

  static async upsertActiveSeat(input: UpsertSeatInput): Promise<void> {
    const prisma = getPrisma() as any;
    const now = new Date();
    const schemaVersion = input.schemaVersion ?? 1;

    await prisma.$transaction(async (tx: any) => {
      // Row-level lock on table rows to reduce double-seat races under concurrent joins.
      await tx.$queryRawUnsafe(
        "SELECT id FROM TableSeatSession WHERE tableId = ? FOR UPDATE",
        input.tableId,
      );

      const conflicting = await tx.tableSeatSession.findFirst({
        where: {
          tableId: input.tableId,
          seat: input.seat,
          state: { in: ["SEATED_ACTIVE", "SEATED_SITTING_OUT"] },
          userId: { not: input.userId },
        },
      });
      if (conflicting) {
        throw new Error("SEAT_CONFLICT");
      }

      await tx.tableSeatSession.upsert({
        where: { tableId_userId: { tableId: input.tableId, userId: input.userId } },
        create: {
          tableId: input.tableId,
          userId: input.userId,
          seat: input.seat,
          state: "SEATED_ACTIVE",
          stackCentsSnapshot: input.stackCentsSnapshot,
          buyInCents: input.buyInCents,
          handIdSnapshot: input.handIdSnapshot,
          disconnectAt: null,
          lastSeenAt: now,
          schemaVersion,
        },
        update: {
          seat: input.seat,
          state: "SEATED_ACTIVE",
          stackCentsSnapshot: input.stackCentsSnapshot,
          buyInCents: input.buyInCents,
          handIdSnapshot: input.handIdSnapshot,
          disconnectAt: null,
          lastSeenAt: now,
          schemaVersion,
        },
      });
    });
  }

  static async markSittingOut(params: {
    tableId: string;
    userId: string;
    stackCentsSnapshot?: number;
    handIdSnapshot?: string;
  }): Promise<void> {
    const prisma = getPrisma() as any;
    await prisma.tableSeatSession.updateMany({
      where: { tableId: params.tableId, userId: params.userId },
      data: {
        state: "SEATED_SITTING_OUT" as SeatSessionState,
        disconnectAt: new Date(),
        lastSeenAt: new Date(),
        ...(typeof params.stackCentsSnapshot === "number" ? { stackCentsSnapshot: params.stackCentsSnapshot } : {}),
        ...(params.handIdSnapshot ? { handIdSnapshot: params.handIdSnapshot } : {}),
      },
    });
  }

  static async markLeft(params: {
    tableId: string;
    userId: string;
    reason?: string;
    stackCentsSnapshot?: number;
    handIdSnapshot?: string;
  }): Promise<void> {
    const prisma = getPrisma() as any;
    await prisma.tableSeatSession.updateMany({
      where: { tableId: params.tableId, userId: params.userId },
      data: {
        state: "LEFT" as SeatSessionState,
        disconnectAt: null,
        lastSeenAt: new Date(),
        ...(typeof params.stackCentsSnapshot === "number" ? { stackCentsSnapshot: params.stackCentsSnapshot } : {}),
        ...(params.handIdSnapshot ? { handIdSnapshot: params.handIdSnapshot } : {}),
      },
    });
  }

  static async listSittingOutDisconnectTimesForUsers(params: {
    tableId: string;
    userIds: string[];
  }): Promise<SittingOutSessionTimestamp[]> {
    if (params.userIds.length === 0) return [];
    const prisma = getPrisma() as any;
    const rows: SittingOutSessionTimestamp[] = await prisma.tableSeatSession.findMany({
      where: {
        tableId: params.tableId,
        userId: { in: params.userIds },
        state: "SEATED_SITTING_OUT",
      },
      select: {
        userId: true,
        disconnectAt: true,
      },
    });
    return rows;
  }

  /** Mark all seat sessions for a table as LEFT. Used when table is deleted. */
  static async markAllLeftForTable(params: { tableId: string }): Promise<void> {
    const prisma = getPrisma() as any;
    await prisma.tableSeatSession.updateMany({
      where: { tableId: params.tableId, state: { in: ["SEATED_ACTIVE", "SEATED_SITTING_OUT"] } },
      data: { state: "LEFT" as SeatSessionState, lastSeenAt: new Date() },
    });
  }

  static async touchConnected(params: {
    tableId: string;
    userId: string;
    stackCentsSnapshot?: number;
    handIdSnapshot?: string;
  }): Promise<void> {
    const prisma = getPrisma() as any;
    await prisma.tableSeatSession.updateMany({
      where: { tableId: params.tableId, userId: params.userId },
      data: {
        state: "SEATED_ACTIVE" as SeatSessionState,
        disconnectAt: null,
        lastSeenAt: new Date(),
        ...(typeof params.stackCentsSnapshot === "number" ? { stackCentsSnapshot: params.stackCentsSnapshot } : {}),
        ...(params.handIdSnapshot ? { handIdSnapshot: params.handIdSnapshot } : {}),
      },
    });
  }
}
